@Test
public void testFlushDoesNotDelegate() throws IOException {
    final OutputStream delegate = Mockito.mock(OutputStream.class);
    final NonFlushableOutputStream nonFlushable = new NonFlushableOutputStream(delegate);
    nonFlushable.flush();
    nonFlushable.write("Hello World".getBytes());
    nonFlushable.flush();
    nonFlushable.close();
    verify(delegate, times(1)).close();
    verify(delegate, times(0)).flush();
}

