private void processMultipleRecordsAssertProvenance(final boolean endpointOverridden) {
    final Date firstDate = Date.from(Instant.now().minus(1, ChronoUnit.MINUTES));
    final Date secondDate = new Date();
    final ProcessRecordsInput processRecordsInput = ProcessRecordsInput.builder().records(Arrays.asList(KinesisClientRecord.builder().approximateArrivalTimestamp(firstDate.toInstant()).partitionKey("partition-1").sequenceNumber("1").data(ByteBuffer.wrap("{\"record\":\"1\"}\n{\"record\":\"1b\"}".getBytes(StandardCharsets.UTF_8))).build(), KinesisClientRecord.builder().approximateArrivalTimestamp(null).partitionKey("partition-no-date").sequenceNumber("no-date").data(ByteBuffer.wrap("{\"record\":\"no-date\"}".getBytes(StandardCharsets.UTF_8))).build(), KinesisClientRecord.builder().approximateArrivalTimestamp(secondDate.toInstant()).partitionKey("partition-2").sequenceNumber("2").data(ByteBuffer.wrap("{\"record\":\"2\"}".getBytes(StandardCharsets.UTF_8))).build())).checkpointer(checkpointer).cacheEntryTime(null).cacheExitTime(null).millisBehindLatest(null).build();
    final String transitUriPrefix = endpointOverridden ? "https://another-endpoint.com:8443" : "http://endpoint-prefix.amazonaws.com";
    if (endpointOverridden) {
        fixture = new KinesisRecordProcessorRecord(processSessionFactory, runner.getLogger(), "kinesis-test", "endpoint-prefix", "https://another-endpoint.com:8443", 10_000L, 1L, 2, DATE_TIME_FORMATTER, reader, writer);
    }
    // skip checkpoint
    fixture.setNextCheckpointTimeInMillis(System.currentTimeMillis() + 10_000L);
    fixture.setKinesisShardId("another-shard");
    when(processSessionFactory.createSession()).thenReturn(session);
    fixture.processRecords(processRecordsInput);
    verify(processSessionFactory, times(1)).createSession();
    session.assertTransferCount(ConsumeKinesisStream.REL_SUCCESS, 1);
    assertEquals(1, sharedState.getProvenanceEvents().size());
    assertEquals(String.format("%s/another-shard", transitUriPrefix), sharedState.getProvenanceEvents().getFirst().getTransitUri());
    final List<MockFlowFile> flowFiles = session.getFlowFilesForRelationship(ConsumeKinesisStream.REL_SUCCESS);
    // 4 records in single output file, attributes equating to that of the last record
    assertFlowFile(flowFiles.get(0), secondDate, "partition-2", "2", "another-shard", "{\"record\":\"1\"}\n" + "{\"record\":\"1b\"}\n" + "{\"record\":\"no-date\"}\n" + "{\"record\":\"2\"}", 4);
    session.assertTransferCount(ConsumeKinesisStream.REL_PARSE_FAILURE, 0);
    session.assertCommitted();
    session.assertNotRolledBack();
}

