        GenericRecord record = null;
        while (dataFileReader.hasNext()) {
            record = dataFileReader.next(record);
            Object o = record.get("t_clob");
            assertTrue(o instanceof Utf8);
            assertEquals("test clob", o.toString());
        }
    }
