    runner.enableControllerService(sslContextService);
    runner.setProperty(ListenOTLP.SSL_CONTEXT_SERVICE, SERVICE_ID);
    runner.setProperty(ListenOTLP.CLIENT_AUTHENTICATION, ClientAuth.WANT.name());
}

