@Test
public void testApproveBasedOnUser() {
    AbstractPolicyBasedAuthorizer authorizer = Mockito.spy(AbstractPolicyBasedAuthorizer.class);
    UsersAndAccessPolicies usersAndAccessPolicies = Mockito.spy(UsersAndAccessPolicies.class);
    when(authorizer.getUsersAndAccessPolicies()).thenReturn(usersAndAccessPolicies);
    final String userIdentifier = "userIdentifier1";
    final String userIdentity = "userIdentity1";
    final AccessPolicy policy = new AccessPolicy.Builder().identifier("1").resource(TEST_RESOURCE.getIdentifier()).addUser(userIdentifier).action(RequestAction.READ).build();
    when(usersAndAccessPolicies.getAccessPolicy(TEST_RESOURCE.getIdentifier(), RequestAction.READ)).thenReturn(policy);
    final User user = new User.Builder().identity(userIdentity).identifier(userIdentifier).build();
    when(usersAndAccessPolicies.getUser(userIdentity)).thenReturn(user);
    final AuthorizationRequest request = new AuthorizationRequest.Builder().identity(userIdentity).resource(TEST_RESOURCE).action(RequestAction.READ).accessAttempt(true).anonymous(false).build();
    assertEquals(AuthorizationResult.approved(), authorizer.authorize(request));
}

