void testRemoveAuthorizationRequestFound() {
    final String identifier = UUID.randomUUID().toString();
    httpServletRequest.setCookies(new Cookie(ApplicationCookieName.OIDC_REQUEST_IDENTIFIER.getCookieName(), identifier));
