    verify(toProvider).saveFlowContent(eq(new StandardFlowSnapshotContext.Builder(BucketMappings.map(bucketEntity), FlowMappings.map(bucketEntity, flowEntity), FlowMappings.map(bucketEntity, flowSnapshotEntity)).build()), AdditionalMatchers.aryEq(getContent(bucketEntity.getId(), flowSnapshotEntity.getFlowId(), flowSnapshotEntity.getVersion())));
}

